(()=>{'use strict';const doc=document;const zonas=doc.querySelectorAll('.grafico');if(!zonas.length)return;const tip=doc.createElement('div');tip.className='g-tip';tip.setAttribute('role','presentation');tip.hidden=true;doc.body.appendChild(tip);let actual=null;const pintar=(fila)=>{if(fila===actual)return;actual=fila;tip.replaceChildren();String(fila.getAttribute('data-tip')||'').split('|').forEach((linea,i)=>{const p=doc.createElement(i===0?'strong':'span');p.textContent=linea;tip.appendChild(p);});};const ubicar=(x,y)=>{const ancho=tip.offsetWidth;const alto=tip.offsetHeight;let izq=x+16;let arriba=y+16;if(izq+ancho>window.innerWidth-8)izq=Math.max(8,x-ancho-16);if(arriba+alto>window.innerHeight-8)arriba=Math.max(8,y-alto-16);tip.style.transform='translate('+Math.round(izq)+'px, '+Math.round(arriba)+'px)';};const ocultar=()=>{tip.hidden=true;if(actual)actual.classList.remove('es-activa');actual=null;};zonas.forEach((zona)=>{zona.addEventListener('pointermove',(e)=>{const fila=e.target instanceof Element?e.target.closest('[data-tip]'):null;if(!fila){ocultar();return;}
if(actual&&actual!==fila)actual.classList.remove('es-activa');pintar(fila);fila.classList.add('es-activa');tip.hidden=false;ubicar(e.clientX,e.clientY);});zona.addEventListener('pointerleave',ocultar);});window.addEventListener('scroll',ocultar,{passive:true});doc.addEventListener('keydown',(e)=>{if(e.key==='Escape')ocultar();});})();
